use std::{fs::{File, OpenOptions}, io::{self, Write}, path::{Path, PathBuf}, sync::{Arc, Mutex}, time::{SystemTime, UNIX_EPOCH}};
#[derive(Clone, Debug)] pub struct Logger { file: Arc<Mutex<File>>, pub path: PathBuf }
impl Logger { pub fn open(dir: &Path) -> io::Result<Self> { std::fs::create_dir_all(dir)?; let path = dir.join("latest.log"); let file = OpenOptions::new().create(true).truncate(true).write(true).open(&path)?; Ok(Self { file: Arc::new(Mutex::new(file)), path }) } pub fn log(&self, level: &str, message: &str) -> io::Result<()> { let stamp = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_secs(); let mut file = self.file.lock().map_err(|_| io::Error::other("logger lock poisoned"))?; writeln!(file, "[{stamp}] [{level}] {message}")?; file.flush() } pub fn info(&self, message: &str) -> io::Result<()> { self.log("INFO", message) } pub fn warn(&self, message: &str) -> io::Result<()> { self.log("WARN", message) } pub fn error(&self, message: &str) -> io::Result<()> { self.log("ERROR", message) } }
